using System;using System.Collections.Generic;using System.Diagnostics;using System.Linq;using System.Net;using System.Net.Sockets;using System.Text;using System.Text.RegularExpressions;using System.Threading;
namespace PZ3D {static class ServerPublicRules {
 public static string Description(byte[] bytes){try{if(bytes==null||bytes.Length<7||bytes.Length>262144||!bytes.Take(5).SequenceEqual(new byte[]{255,255,255,255,69}))return null;int count=bytes[5]|bytes[6]<<8;if(count>2048)return null;int at=7;var pairs=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);for(int n=0;n<count;n++){string k=Read(bytes,ref at),v=Read(bytes,ref at);if(pairs.ContainsKey(k))return null;pairs[k]=v;}if(at!=bytes.Length)return null;string direct;if(pairs.TryGetValue("description",out direct)||pairs.TryGetValue("PublicDescription",out direct))return direct;var chunks=new SortedDictionary<int,string>();int total=0;foreach(var p in pairs){var m=Regex.Match(p.Key,@"^description:(\d+)/(\d+)$",RegexOptions.IgnoreCase);if(!m.Success)continue;int i=int.Parse(m.Groups[1].Value),t=int.Parse(m.Groups[2].Value);if(t<1||t>256||i<1||i>t||total!=0&&total!=t||chunks.ContainsKey(i))return null;total=t;chunks[i]=p.Value;}if(total==0||chunks.Count!=total)return null;string result=string.Concat(chunks.Values);return result.Length<=65536?result:null;}catch{return null;}}
 static string Read(byte[] b,ref int at){int start=at;while(at<b.Length&&b[at]!=0)at++;if(at>=b.Length||at-start>65536)throw new Exception();string text=new UTF8Encoding(false,true).GetString(b,start,at-start);at++;return text;}
 public static string Query(UdpClient udp,CancellationToken token,out string warning){warning="";try{byte[] request={255,255,255,255,86,255,255,255,255};udp.Send(request,request.Length);var clock=Stopwatch.StartNew();bool challenged=false;uint? serial=null;int total=0;var fragments=new Dictionary<int,byte[]>();while(clock.ElapsedMilliseconds<1400){token.ThrowIfCancellationRequested();if(!udp.Client.Poll(50000,SelectMode.SelectRead))continue;IPEndPoint ep=null;byte[] packet=udp.Receive(ref ep);if(packet.Length<5)continue;if(packet.Length==9&&packet.Take(5).SequenceEqual(new byte[]{255,255,255,255,65})&&!challenged){challenged=true;Array.Copy(packet,5,request,5,4);udp.Send(request,request.Length);continue;}if(packet.Take(4).All(x=>x==255)){string result=Description(packet);if(result!=null)return result;continue;}if(packet.Length<12||!packet.Take(4).SequenceEqual(new byte[]{254,255,255,255}))continue;uint id=BitConverter.ToUInt32(packet,4);if((id&0x80000000)!=0){warning="服务器介绍使用压缩包，当前不支持；人数仍可读取。";return null;}int t=packet[8],n=packet[9];if(t<1||t>64||n>=t||serial.HasValue&&serial.Value!=id||total!=0&&total!=t)throw new Exception();serial=id;total=t;byte[] part=packet.Skip(12).ToArray();if(fragments.ContainsKey(n)&&!fragments[n].SequenceEqual(part))throw new Exception();fragments[n]=part;if(fragments.Values.Sum(b=>b.Length)>262144)throw new Exception();if(fragments.Count==total){byte[] all=Enumerable.Range(0,total).SelectMany(i=>fragments[i]).ToArray();if(all.Length>=9&&all.Take(8).All(x=>x==255))all=all.Skip(4).ToArray();string result=Description(all);if(result!=null)return result;throw new Exception();}}warning="人数查询成功，但介绍规则未返回或不完整。";}catch(OperationCanceledException){throw;}catch{warning="服务器介绍规则格式不支持或未完整返回。";}return null;}
}}
